// Syntax: condition ? result_true : result_false

int a = 10, b = 5;
int max_val;

// Conditional Assignment
max_val = (a > b) ? a : b; // max_val is 10

// Must produce the same type/compatible types
float f_val = 15.5f;
int limit = 20;

// Returns 1.0 or 0.5 (as float)
float factor = (f_val < limit) ? 1.0f : 0.5f;

// Use as function argument
printf("Result: %s", (max_val > 10) ? "High" : "Low");
